void post_reset_init_lpddr4(void);

void imem_load_1D_0(void);
void imem_load_1D_1(void);
void dmem_load_1D(void);

#define REG_WRITE(REG_NAME,  REG_VALUE)		(*(volatile int32_t *)(uintptr_t)REG_NAME= REG_VALUE)

int32_t REG_READ(uintptr_t REG_NAME) {
	int32_t value = *(volatile int32_t *)REG_NAME;
	return value;
}

void NOP(void)
{
	asm volatile("nop;");
}

//#define SSYNC asm ("sync;")

void SSYNC(void)
{
	asm("isb;");
}

void _delay (uint32_t value)
{
	for (uint32_t i = value; i > 0ul; i--) {
		NOP();
	}

}

int32_t get_mail(uint8_t mode) {
	int32_t mail, mail_0, mail_1;
	if(mode==1) {REG_WRITE(REG_LPDDRMISC_DBG_CTL0,0xFFFFFFFF);}  // For Polling

	while(((REG_READ(REG_LPDDR4_PHY_APB_UCTSHADOWREGS)) & 0x01)!=0x0) { asm("NOP"); }
	mail_0 = REG_READ(REG_LPDDR4_PHY_APB_UCTWRITEONLYSHADOW);

	if(mode==1){
		mail_1 = REG_READ(REG_LPDDR4_PHY_APB_UCTDATWRITEONLYSHADOW);
		mail   = (mail_1 <<16) | mail_0;
		REG_WRITE(REG_LPDDRMISC_DBG_CTL0,mail);
	}
	else
	{
		mail = mail_0;
		REG_WRITE(REG_LPDDRMISC_DBG_CTL0,(mail | 0xFFFF0000));
	}

	REG_WRITE(REG_LPDDR4_PHY_APB_DCTWRITEPROT,0x0);
	while(((REG_READ(REG_LPDDR4_PHY_APB_UCTSHADOWREGS)) & 0x01)!=0x1) { asm("NOP"); }
	REG_WRITE(REG_LPDDR4_PHY_APB_DCTWRITEPROT,0x1);

	return mail;
}


//-------------------Streaming Messages-------------------

void get_streaming_msg(void)
{
	int32_t string_index,arg;
	int i = 1;

	string_index = get_mail(1);
	while(i <= (string_index & 0xFFFF))
	{
		arg = get_mail(1);
		i = i+1;
	}
}

void waitFWDone(void)
{
	int32_t maj_msg;
	do
	{
		maj_msg = get_mail(0);
		if (maj_msg == 0x08){
			get_streaming_msg();
		}
	}
	while ((maj_msg != 0x07) && (maj_msg != 0xFF));
}

