	REG_WRITE(REG_LPDDR4_DBG1,0x00000002);\
	while(REG_READ(REG_LPDDR4_INIT0)!=0xc0020002) { asm("NOP"); }\
	while(REG_READ(REG_LPDDR4_DBICTL)!=0x00000001) { asm("NOP"); }\
	while(REG_READ(MOD_UMCTL2_REGS_BASE)!=0x03080020) { asm("NOP"); }\
